    public int solve(int left, int right) {
        // Initialize an array to store whether the current position is "first" or "second".
        boolean[][] memo = new boolean[10][10];
        // Set all positions to unmarked initially.
        for (int i = 0; i < 10; i++) {
            for (int j = 0; j < 10; j++) {
                memo[i][j] = false;
