import heapq

def dijkstra(n, edges, s, t):
    adj = [[] for _ in range(n)]
    dist = [float('inf')] * n
    parent = [-1] * n
    heap = [(0, s)]

    while heap:
        d, u = heapq.heappop(heap)
        if u == t:
            break
        if d > dist[u]:
            continue
        for v, w in adj[u]:
            if d + w < dist[v]:
                dist[v] = d + w
                parent[v] = u
                heapq.heappush(heap, (dist[v], v))

    if dist[t] == float('inf'):
        return -1
    else:
        path = [t]
        while path[-1] != s:
            path.append(parent[path[-1]])
        path.reverse()
        return dist[t]

def solve(n, edges, s, t):
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))
    return dijstra(n, adj, s, t)
