import numpy as np

def unlabeled(v):
    def is_label(x, y, color):
        if x < 0 or y < 0 or x >= v.shape[0] or y >= v.shape[1]:
            return False
        if v[x, y] == color:
            v[x, y] = -1
            return True
        return False

    def dfs(x, y, color):
        if not is_label(x, y, color):
            return
        for dx, dy in ((x, y), (x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
            dx, dy = dx % v.shape[0], dy % v.shape[1]
            dfs(dx, dy, color)

    labels = []
    num_labels = 0
    for i in range(v.shape[0]):
        for j in range(v.shape[1]):
            if v[i, j] != -1:
                color = v[i, j]
                if color != 0:
                    dfs(i, j, color)
                    labels.append((i, j, color))
                    num_labels += 1

    if num_labels == 1:
        return True, 1
    else:
        return False, num_labels

