int solve(int n, const vector<Edge>& edges, int s, int t) {
    // Create an adjacency list for the graph
    vector<vector<pair<int, int>>> adjList(n);
    for (const auto& edge : edges) {
        adjList[edge.start].emplace_back(edge.end, edge.weight);
    }

    // Priority queue to store the nodes to visit next
    // Each element in the queue is a pair of (distance, node)
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
    pq.push({0, s});

    // Array to store the minimum distance from the source to each node
    vector<int> minDistances(n, INT_MAX);
    minDistances[s] = 0;

    while (!pq.empty()) {
        int currentDistance = pq.top().first;
        int currentNode = pq.top().second;
        pq.pop();

        // If we have reached the target node, return its distance
        if (currentNode == t) {
            return currentDistance;
        }

        // Explore all neighbors of the current node
        for (const auto& neighbor : adjList[currentNode]) {
            int neighborNode = neighbor.first;
            int weight = neighbor.second;

            // Calculate the distance to the neighbor via the current node
            int newDistance = currentDistance + weight;

            // If this is a shorter path to the neighbor node
            if (newDistance < minDistances[neighborNode]) {
                minDistances[neighborNode] = newDistance;
                pq.push({newDistance, neighborNode});
            }
        }
    }

    // If the target node is not reachable from the source node, return -1
    return -1;
}

