def shortest_path(n, edges, s, t):
    # helper function to convert edges into a dictionary
    def build_graph(edges):
        graph = {i: [] for i in range(n)}
        for u, v, w in edges:
            graph[u].append((v, w))
        return graph

    # helper function to find the shortest path
    def shortest_path(graph, start, end):
        distances = [float('inf')] * n
        distances[start] = 0
        queue = [start]
        while queue:
            current = queue.pop(0)
            for neighbor, weight in graph[current]:
                new_distance = distances[current] + weight
                if new_distance < distances[neighbor]:
                    distances[neighbor] = new_distance
                    queue.append(neighbor)
        return distances[end] if distances[end] < float('inf') else -1

    graph = build_graph(edges)
    return shortest_path(graph, s, t)

