from collections import defaultdict, deque

def has_cycle(graph):
    n = len(graph)
    visited = [False] * n
    predecessor = [None] * n

    def dfs(u):
        visited[u] = True
        for neighbor in graph[u]:
            if visited[neighbor]:
                if predecessor[neighbor] != u:
                    return True
            else:
                predecessor[neighbor] = u
                if dfs(neighbor):
                    return True
        return False

    for node in range(n):
        if not visited[node] and dfs(node):
            return True
    return False

def solve(n, edges, s, t):
    if s == t:
        return 0
    if has_cycle(edges):
        return None

    graph = defaultdict(list)
    weight = {}

    for u, v, w in edges:
        graph[u].append((v, w))
        weight[(u, v)] = w

    queue = deque([s])
    distances = [float('inf')] * n
    distances[s] = 0

    while queue:
        current = queue.popleft()
        for neighbor, weight in graph[current]:
            if distances[current] + weight < distances[neighbor]:
                distances[neighbor] = distances[current] + weight
                queue.append(neighbor)

    return distances[t] if distances[t] != float('inf') else -1
