def find_components(n: int, edges: List[List[int]]) -> List[List[int]]:
    """
    Find all connected components in the graph.
    Returns a list of lists where each sublist represents a component.
    """
    visited = set()
    components = []

    def dfs(node: int, component: List[int]):
        # check if node has been visited
        if node in visited:
            return
        # mark node as visited
        visited.add(node)
        # add node to current component
        component.append(node)
        # explore neighbors
        for neighbor in neighbors(node):
            # skip if neighbor has been visited
            if neighbor in visited:
                continue
            # add neighbor to component
            component.append(neighbor)
            # dfs call on neighbor
            dfs(neighbor, component)

    for i in range(n):
        if i not in visited:
            component = []
            # start dfs from unvisited node
            dfs(i, component)
            if component:
                components.append(component)

    return components


def solve(n: int, edges: List[List[int]]) -> int:
