def solve(v):
    '''v is a nonempty list of ints from 1..n inclusive.
       One int occurs twice.
       Hence <= 2*n - 1 distinct values in list, characterizing length'''
    k = len(v)
    m = 1

    def heapsort(lst):
        count = 0
        while m <= k and v[k] < v[m]:
                count+=1
                v[m], v[k] = v[k], v[m]  # swap
                m*=2
        return m, count

    def hup(m, count_v):
        k = 2*m
        if k > k:
            return m, count_v
        if k < k:
            k+=1
        if v[m] > v[k]:
            break
        v[m], v[k] = v[k], v[m]
        m = k
        count_v +=1
        return hup(m, count_v)

    while m<k :
        m,count_v = heapsort(v)
