from functools import lru_cache

@lru_cache(maxsize=None)
def is_free(grid, row, col):
    return row >= 0 and row < len(grid) and col >= 0 and col < len(grid[0]) and grid[row][col] == '.'

def solve(grid, start, goal):
    @lru_cache(maxsize=None)
    def dfs(row, col):
        if not is_free(grid, row, col) or (row, col) == start: return []
        if (row, col) == goal: return [(row, col)]

        return min(
            [current] + dfs(next_row, next_col)
            for direction in [(0, 1), (0, -1), (1, 0), (-1, 0)]
            for next_row, next_col in [(row + direction[0], col + direction[1])]
            if is_free(grid, next_row, next_col)
            for current in [((row, col), dfs(next_row, next_col))],
            key=lambda x: len(x[-1]), default=[]
        )

    return dfs(*start)
