    def is_free_cell(cell):
        row, col = cell
        return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] == '.'

    def move(cell):
        row, col = cell
        neighbours = [(row-1, col), (row+1, col), (row, col-1), (row, col+1)]
        return [n for n in neighbours if is_free_cell(n)]

    def dfs(cell, visited):
        if cell == goal:
            return [cell]
        visited.add(cell)
        for next_cell in move(cell):
            if next_cell not in visited:
                path = dfs(next_cell, visited)
                if path is not None:
                    return [cell] + path
        return None

    visited = set()
    path = dfs(start, visited)
    return path if path is not None else []

