    rows, cols = len(grid), len(grid[0])

    def neighbors(r, c):
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                yield nr, nc

    def dfs(r, c, visited):
        if (r, c) == goal:
            return True
        visited.add((r, c))
        for nr, nc in neighbors(r, c):
            if (nr, nc) not in visited:
                if dfs(nr, nc, visited):
                    return True
        return False

    if not (0 <= start[0] < rows and 0 <= start[1] < cols and grid[start[0]][start[1]] == '.') or \
       not (0 <= goal[0] < rows and 0 <= goal[1] < cols and grid[goal[0]][goal[1]] == '.'):
        return []

    if start == goal:
        return [start]

    if not dfs(start[0], start[1], set()):
        return []

    path = []
    stack = [(start, [start])]
    visited = set()
    visited.add(start)

    while stack:
        (r, c), trail = stack.pop()
        if (r, c) == goal:
            path = trail
            break
        for nr, nc in neighbors(r, c):
            if (nr, nc) not in visited:
                visited.add((nr, nc))
                stack.append(((nr, nc), trail + [(nr, nc)]))

    return path if path[0] == start and path[-1] == goal else []
