int BINARY_SEARCH(std::vector& v, int target) {
    int left = 0;
    int right = v.size() - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (v[mid] == target) {
            return mid;
        } else if (v[mid] < target) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return -1;
};

int BINARY_SEARCH_REC(std::vector& v, int target, int left, int right) {
    if (left > right) {
        return -1;
    }
    int mid = left + (right - left) / 2;
    if (v[mid] == target) {
        return mid;
    } else if (v[mid] < target) {
        return BINARY_SEARCH_REC(v, target, mid + 1, right);
    } else {
        return BINARY_SEARCH_REC(v, target, left, mid - 1);
    }
};

