def solve(grid, start, goal):
    R, C = len(grid), len(grid[0])

    def is_valid(row, col):
        return 0 <= row < R and 0 <= col < C and grid[row][col] == '.'

    def get_neighbors(row, col):
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            new_row, new_col = row + dr, col + dc
            if is_valid(new_row, new_col):
                yield (new_row, new_col)

    if not is_valid(start[0], start[1]):
        return False

    if not is_valid(goal[0], goal[1]):
        return False

    if start == goal:
        return [start]

    visited, stack = set(), []

    stack.append(start)

    while stack:
        curr = stack.pop()
        if curr == goal:  # is it the goal?
            return [ curr ]
        visited.add(curr)  # mark curr as visited

        new_neighbors = [n for n in get_neighbors(curr[0], curr[1]) if n not in visited]
        stack.extend(new_neighbors)

    return []
