def solve(grid, start, goal):
    """ Find a path between start and goal cells in the grid. """

    def is_free(row, col):
        """ Check if a cell is free. """
        if row < 0 or row >= len(grid) or col < 0 or col >= len(grid[0]):
            return False
        return grid[row][col] == '.'

    def get_neighbors(row, col):
        """ Get the valid neighbors of a cell. """
        neighbors = [(row+1, col), (row-1, col), (row, col+1), (row, col-1)]
        return [n for n in neighbors if is_free(*n)]

    def find_path(current, goal, path_so_far):
        """ Recursively find a path to the goal. """
        if current == goal:
            return path_so_far + [current]
        for neighbor in get_neighbors(*current):
            if neighbor in path_so_far:
                continue
            new_path = find_path(neighbor, goal, path_so_far + [current])
            if new_path:
                return new_path

