import heapq

def solve(nums):
    # Create a min heap from nums.
    heap = list(nums)
    heapq.heapify(heap)

    # Create a dictionary to store the smallest greatest element ending at each index.
    sge = {}
    sge[0] = heap[0]

    # Find the smallest greatest element for each index.
    for i in range(1, len(nums)):
        if nums[i] > sge[i-1]:
            sge[i] = nums[i]
        else:
            # Use binary search on the heap to find the position where nums[i] would fit.
            position = binary_search(heap, nums[i])
            sge[i] = heap[position+1] if position+1 < len(heap) else nums[i]

    return len(heap)

# Helper function to perform binary search on a heap.
def binary_search(heap, target):
    left, right = 0, len(heap)-1
    while left <= right:
        mid = (left + right) // 2
        if heap[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return left

