def solve(nums):
    def longest_increasing_subsequence(start_index):
        longest = [start_index]
        current = longest[-1]
        next_index = start_index + 1
        while next_index < len(nums):
            if nums[next_index] > nums[current]:
                longest.append(next_index)
                current = longest[-1]
                next_index += 1
            else:
                return longest

    candidate_values = dict()
    next_index = 1
    while next_index < len(nums):
        key_value = nums[next_index]
        cutoff = nums[next_index - 1]
        if key_value > cutoff:
            candidate_values[key_value] = candidate_values.get(key_value, []
                                                 ) + [next_index]

        next_index += 1

    subsequences = list()
    for cutoff in candidate_values.values():
        for subsequence in map(longest_increasing_subsequence,
                               [cutoff[-1]] + cutoff):
            subsequences.append(subsequence)

