import java.util.List;

public class Solution {
    public int longestIncreasingSubsequence(int[] nums) {
        List<List<Integer>> nList = new ArrayList<>();
        List<List<Integer>> sList = new ArrayList<>();

        for (int i = 0; i < nums.length; ++i) {
            nList.add(new ArrayList<>());
            sList.add(new ArrayList<>());
        }

        for (int i = 1; i < nums.length; ++i) {
            if (nums[i] > nums[i - 1]) sList.get(i).add(i);
            for (int j = 0; j <= i - 1; ++j) {
                if (nums[i] > nums[j]) nList.get(i).add(j);
            }
        }

        return Math.max((solve(1, nList, sList)), 1);
    }

    public int solve(int cur, List<List<Integer>> nList, List<List<Integer>> sList) {
        if (nList.get(cur).isEmpty()) return 0;
        int max = 1;

        for (int next : nList.get(cur)) {
            int len = sList.get(next).size();
            if (sList.get(next).contains(cur)) len = 0;
            else max = Math.max(max, solve(next, nList, sList) + len);
        }

        return max;
    }
}
