def nth_smallest_value(nums, k):
	smallest = [str(max(nums))]
	higher = []
	set_smallest = set()

	for i in range(k):

		while smallest != []:
			# remove smallest and return previously deleted number + lower number + discarded number
			value = smallest.pop(0)

			# if previously deleted number isn't taken, discard it
			if value in set_smallest:
				pass
			elif value == nums[i-1]:
				set_smallest.add(value)
				pass
			else:
				return value

			# if number isn't found, push onto higher, add to set unless repeated
			try:
				if int(nums[i]) < int(value): 
					higher.append(nums[i])
					if not nums[i] in set_smallest:
						set_smallest.add(nums[i])

			except ValueError:
				higher.append(nums[i])

		smallest[:] = higher[:]
		higher = []

	for j in range(k):
		try:
			i += 1
			if int(value) >= int(nums[i]):
				value = nth_smallest_value(nums,k-j)
		except UnboundLocalError:
			continue

	return None


