    def partition(l, r):
        # make the leftmost value the pivot
        pivot = l
        # pivot value
        val = nums[pivot]
        # put all values less than val to the left
        # put all values greater than val to the right
        while l != r:
            # if the current value to the right is smaller, increment
            if nums[l] < val:
                l += 1
            # if the current value to the left is greater, decrement
            elif nums[r] > val:
                r -= 1
            # if the current values are on the wrong sides, bring them into place
            else:
                nums[l], nums[r] = nums[r], nums[l]
        # everything after this is out-of-place
        # we need to find the right place to put the pivot
        # 
        # I can't guarantee the time complexity of other languages but
        # I can guarantee this implementation isn't linear log time
        if nums[k-1] >= pivot:
            for i in range(l - 1, len(nums)-1):
                if nums[i] < val:
                    nums[pivot], nums[i] = nums[i], nums[pivot]
                    break
        else:
            for i in range(r + 1, len(nums)):
                if nums[i] > val:
