def is_connected(G):
    s = G[0][0]
    x = {s}
    y = [s]
    while y:
        s = y.pop()
        for e in G:
            if e[0] == s and e[1] not in x:
                x.add(e[1])
                y.append(e[1])
    return len(x) == len(G) - 1


