def _dijkstra(edges, n, last_node, first_node=0):
    d = [float('inf') for _ in range(n)]
    visited = [False for _ in range(n)]
    d[first_node] = 0
    for _ in range(n):
        visited_node = -1
        for u,_ in enumerate(visited):
            if not visited[u] and (visited_node == -1 or d[u]<d[visited_node]):
                visited_node = u
        list_ = []
        visited[visited_node] = True
        for u, v, w in edges:
            if u == visited_node and not visited[v]:
                if first_node == u and last_node == v:
                    return d[v]
                if d[u]+w < d[v]:
                    d[v] = d[u]+w
    return d[last_node]

