def bfs(s, graph):
    visited = []
    queue = [[s]]
    while queue:
        path = queue.pop(0)
        node = path[-1]
        if node not in visited:
            visited.append(node)
            for edge in graph[node]:
                new_path = list(path)
                new_path.append(edge[0])
                queue.append(new_path)
                if edge[0] == s:
                    if new_path in new_path:
                        return visited
    return visited


