    while x != tar:
        tar = path[tar]
    return tar

def union(i, j):
    p, q = find(i), find(j)
    if p == q:
        return False
    if size[p] > size[q]:
        p, q = q, p  # swap
    size[q] = size[q] + size[p]
    path[p] = q
    return True

