def _solve(n, edges, components):

    for edge in edges:
        start = edge[0]
        end = edge[1]

        # add new component if start & end have no component yet
        if start not in components:
            components[start] = {}
        if end not in components:
            components[end] = {}

        new_component = False
        # merge start into end
        if end not in components[start]:
            for neighbour in components[start]:
                components[neighbour][end] = True
                components[end][neighbour] = True
            new_component = True
        # merge end into start if not already merged
        elif start not in components[end]:
            for neighbour in components[end]:
                components[start][neighbour] = True
                components[neighbour][start] = True
            new_component = True

        if new_component:
            # remove old component if it is empty
            if not components[start]:
                del components[start]
            if not components[end]:
                del components[end]

    # return the number of elements in components
    return len(components)


