def do_it(n, edges, node, visited):
	# Initialize
	sum = 0

	# No more edges exist. Return component count.
	if len(edges) == 0:
		return node

	# Note node seen
	if node not in visited:
		visited.append(node)

	# Step 1: Iterate through edges
	for edge in edges:

		# Step 2: Look for valid starting point
		for segment in edge:
			# Skip node already visited on this run
			if segment in visited:
				continue

			# If start node is valid, finish the job
			elif segment == 0 and node == segment+1:
				if segment not in visited:
					visited.append(segment)
				sum = 1
				break

			# Step 3: Recursion step
			else:
				# Make adjustment
				if segment == node + 1:
					sum += do_it(n, edges, segment, visited)
					# At the border of an island, jump to next chain and keep going
				elif segment == node - 1:
					sum += do_it(n, edges, segment, visited)

	# If at the end of the line, dump function!
	if node == n - 1:
		return sum

