def solve(n, edges):
    parents = range(n)
    ranks = [0] * n
    res = n

    def find(x):
        nonlocal res
        res += bool(x != parents[x])
        return parents[x]

    def union(x, y):
        xroot = find(x)
        yroot = find(y)
        if xroot == yroot:
            return
        res -= 1
        if ranks[xroot] < ranks[yroot]:
            xroot, yroot = yroot, xroot
        parents[yroot] = xroot
        ranks[xroot] += ranks[xroot] == ranks[yroot]

    for x, y in edges:
        union(x, y)
    return res

