def addConnected(current, graph):
  addedNodes = []
  if graph.get(current):
    connected = graph.get(current)
    for c in connected:
      if c in graph:
        for connectedC in graph.get(c):
          connected.append(connectedC)
      nodes = [x for x in connected if x not in addedNodes]
      addedNodes += nodes
    graph[current] = nodes
  return addedNodes

def make_graph(n, edges):
  graph = {}
  for edge in edges:
    if graph.get(edge[0]):
      e0 = graph.get(edge[0])
      e0.add(edge[1])
      graph[edge[0]] = e0
    else:
      graph[edge[0]] = {edge[1]}
    if graph.get(edge[1]):
      e1 = graph.get(edge[1])
      e1.add(edge[0])
      graph[edge[1]] = e1
    else:
      graph[edge[1]] = {edge[0]}
  return graph

