def moves(curr_pos, grid):
    moves = []
    # check if the cell is a wall
    """
    if isinstance(curr_pos[0], int) and isinstance(curr_pos[1], int):
        if curr_pos[0] in range(len(grid)) and curr_pos[1] in range(len(grid[curr_pos[0]])):
            if grid[curr_pos[0]][curr_pos[1]] == "#":
                return []
    """
    # check if the cell is a wall and add to moves if it is not
    if isinstance(curr_pos[0], int) and isinstance(curr_pos[1], int):
        if curr_pos[0] in range(len(grid)) and curr_pos[1] in range(len(grid[curr_pos[0]])):
            if grid[curr_pos[0]][curr_pos[1]] != "#":
                moves.append(curr_pos)
    # check if the move is in the grid and add to moves if it is not a wall
    # add up to list
    if curr_pos[0] - 1 >= 0:
        if grid[curr_pos[0] - 1][curr_pos[1]] != "#":
            moves.append((curr_pos[0] - 1, curr_pos[1]))
    # add down to list
    if curr_pos[0] + 1 < len(grid):
        if grid[curr_pos[0] + 1][curr_pos[1]] != "#":
            moves.append((curr_pos[0] + 1, curr_pos[1]))
    # add left to list
    if curr_pos[1] - 1 >= 0:
        if grid[curr_pos[0]][curr_pos[1] - 1] != "#":
            moves.append((curr_pos[0], curr_pos[1] - 1))
    # add right to list
    if curr_pos[1] + 1 < len(grid[curr_pos[0]]):
        if grid[curr_pos[0]][curr_pos[1] + 1] != "#":
            moves.append((curr_pos[0], curr_pos[1] + 1))
    return moves

