    neighbours = []
    block_x, block_y = block[0][0], block[0][1]
    potentialUp = block_x - 1, block_y
    potentialDown = block_x + 1, block_y
    potentialLeft = block_x, block_y - 1
    potentialRight = block_x, block_y + 1
    try:
        if visited[potentialUp[0]*size + potentialUp[1]][2]:
            neighbours.append(potentialUp)
    except Exception:
        pass
    try:
        if visited[potentialDown[0]*size + potentialDown[1]][2]:
            neighbours.append(potentialDown)
    except Exception:
        pass
    try:
        if visited[potentialLeft[0]*size + potentialLeft[1]][2]:
            neighbours.append(potentialLeft)
    except Exception:
        pass
    try:
        if visited[potentialRight[0]*size + potentialRight[1]][2]:
            neighbours.append(potentialRight)
    except Exception:
        pass

    return neighbours

