def _solve(grid,start,goal):
    rows, cols = len(grid) , len(grid[0])

    # Record the distance from the start state and use a
    # dynamically growing list to reduce memory consumption.
    distance_from_start = []
    distance_from_start.append([-1] * cols + [[0]])
    distance_from_start.append([-1] * cols + [None])
    for _ in range(rows - 2): # move 2 steps up, assuming legal start position
        distance_from_start.append([-1] * cols + [None])

    # When doing dynamic programming there may be states we do not consider
    # at all, e.g. if there is a wall blocking the way, while exploring paths.
    # In this case we do not dive into marking and tracking these states.
    # Instead, if we encounter a state we already started to explore at later time,
    # we can skip it. For this we keep the position of the move we started to explore
    # and do not go anywhere deeper if the start position is before the one from
    # the call stack.
    start = [start, None, 0]


    def get_distance(row, col):
        if row >= 0 and row <= rows:
            if col >= 0 and col <= cols:
                if grid[row][col] == '.' and distance_from_start[row][col] != -1:
                    return distance_from_start[row][col]
        return None

    def get_steps(row, col):
        if row >= 0 and row <= rows:
            if col >= 0 and col <= cols:
                stepsFrom = distance_from_start[row][col]
                if stepsFrom != -1:
                    return stepsFrom
        return None


    # This marks a neighbour as reached if we are starting to mark all routes
    # from there. If we encounter a state that we have already visited before,
    # we are dealing with a more interesting issue: we have (reached) multiple
    # routes on that position (i.e. they differ in at least one letter).
    # We are only triggering multiple options if we already have multiple
    # options going to the same position, i.e. they differ in at least one
    # letter. This potentially reduces the amount of work we have to do.
    def decide_directions(paths):
        if states_visited[row][col] >= 2:
            paths.remove((col,row))
        states_visited[row][col] += 1
        distance_from_start[row][col] = paths

    # The heuristic function measures the direct (orthogonal) distance, always
    # keeping the X-Plane fast and the Z-coordinate (upwards into space)
    # as small as possible because moving up is presumably cumbersome.
    def heuristic(row,col):
        if row <= goal[0]:
            if col <= goal[1]:
                 return (rows - goal[0]) + (cols - goal[1])
            elif col == cols:
                 if row == 0:      return col - goal[1]
                 elif row == goal[0]: return goal[1]
                 elif row == cols: return col - goal[1]
                 elif row == rows: return 2 * (cols - goal[1])
            else:
                 if row == 0:      return (cols - 1 - col) + (rows - goal[0]) + (goal[1] - 1)
                 elif row == goal[0]: return (cols - 1 - col) + (goal[1] - 1)
                 elif row == cols: return (cols - 1 - col) + (rows - goal[0]) + (goal[1] - 1)
                 elif row == rows: return 2 * (cols - 1 - col)

        elif row == cols:
            if col <= goal[1]:
                 return rows - goal[0]
            elif col == cols:
                 return rows - goal[0]
            else:
                 return (rows - 1 - row) + (cols - goal[1]) + (goal[0] - 1)
        elif row == rows:
            if col <= goal[1]:
                 return (rows - 1 - row) + (cols - goal[1]) + (goal[0] - 1)
            elif col == cols:
                if goal[0] <= rows:
                    return col - goal[1]
                else:
                    return (cols - goal[1])
            else:
                if cols == 1:
                   return row - goal[0]
                else:
                   return 2 * (cols - 1 - col)

        return rows - goal[0

    stack = [start]
    goal_row =goal[0]
    goal_col =goal[1]

