        node = frontier.pop(0)
        explored.add(node)
        children = []
        if node[0] > 0:
            children.append((node[0]-1, node[1]))
        if node[0] < len(grid)-1:
            children.append((node[0]+1, node[1]))
        if node[1] > 0:
            children.append((node[0], node[1]-1))
        if node[1] < len(grid[0])-1:
            children.append((node[0], node[1]+1))
        for child in children:
            if child == goal and grid[child[0]][child[1]] != "#":
                return [node] + [child]
            if grid[child[0]][child[1]] != "#" and child not in explored:
                frontier.append(child) #!?
        if frontier == []:
            break

    return []


