def BinarySearch(nums,length,starting_value):
    left = 1
    right = starting_value
    while(left<=right):
        mid = left + (right - left) // 2
        if nums[mid] < nums[starting_value]:
            left = mid + 1 #nums[mid] is large enough to not be counted as the largest_smaller
        else:
            right = mid - 1
    return left

