class Solution:
    def merge(self, intervals: List[List[int]]) -> List[List[int]]:
        intervals.sort(key=lambda x: x[0])
        res = [intervals[0]]
        for i in range(1, len(intervals)):
            are = res[-1]
            inv = intervals[i]

            if are[1] >= inv[0]:
                are[1] = max(are[1], inv[1])
            else:
                res.append(inv)
        return res

    list_of_lists = sorted([(i, j) for [i,j] in intervals])
    output = [list_of_lists[0]]
    for interval in range(1,len(list_of_lists)):
        begin = list_of_lists[interval][0]
        end = list_of_lists[interval][1]
        output = if_touching(output,begin,end)
    return output

def if_touching(list_of_lists,begin,end):
    if len(list_of_lists) > 1:
        for sub_interval in list_of_lists[-1]:
            if begin < sub_interval +1 or end > sub_interval:
                return list_of_lists[:-1] + [begin,end]
