def answer(names):    
    scores = {}
    for s in scores: 
        scores[s] += 1    
    mapped_scores = {scores[s]:s for s in scores}

    def substring_score(s):
        l = 0
        r = len(s) - 1
        while min(l, r) >= 1 and s[l] == s[r]:
            l += 1
            r -= 1
        if min(l, r) >= 1:
            return ord(s[l]) + (ord(s[l]) - ord(s[r])) * 10
        if l == 1:
            return ord(s[0]) * 100
        return ord(s[0]) * 110

    answer = {}
    for name in names:
        lengths = [substring_score(name)]
        if name in scores:
            lengths[-1] += scores[name]
        for possible_name in scores:
            if name.startswith(possible_name):
                lengths.append(substring_score(name[len(possible_name):]) + scores[possible_name])
        good_name = mapped_scores[max(set(lengths))]
        if good_name not in answer:
            answer[good_name] = 0
        answer[good_name] += 1
    return answer

