def is_overlap(x1, x2):
    if x1[1] < x2[0]:
        return False
    elif x1[1] < x2[1]:
        return True
    elif x1[1] == x2[1]:
        return True
    elif x1[0] < x2[1] and x1[0] > x2[0]:
        return True
    else:
        return False

  # Double array f will contain 1, 0, or -1 for each of max(m * n) potential intersections.
  # f[x][y] = 1 if interval x ends after interval y starts.
  # f[x][y] = 0 if interval x starts before interval y ends.
  # f[x][y] = -1 if interval x ends and interval y starts at the same point.
  f = [[0 for _ in range(len(intervals))] for _ in range(len(intervals))]
  for i, x in enumerate(intervals):
    for j, y in enumerate(intervals):
      if x[1] > y[0]:
        f[i][j] = 1
      elif x[1] == y[0]:
        f[i][j] = -1
      elif x[0] < y[1]:
        f[i][j] = 0

  # Have to go through the entire row, because it might not have the largest possible number
  # at the end. For example, consider a sequence of n + 1 increasing intervals.
  table = [[0 for _ in range(len(intervals))] for _ in range(2)]
  for i in range(1, len(intervals) + 1):
    table[i % 2][0] = 0
    for j in range(1, i):
      if f[i - 1][j - 1] == -1 or f[i - 1][j - 1] == 0:
        table[i % 2][j] = table[(i - 1) % 2][j - 1]
      else:
        table[i % 2][j] = table[(i - 1) % 2][j]
    if f[i - 1][i - 1] == 1:
      table[i % 2][i] = table[(i - 1) % 2][i - 1] + 1
    else:
      table[i % 2][i] = table[(i - 1) % 2][i]

  # The minimum number of intervals that can be compared is 0.
  if int(len(intervals)) == 0:
    # This could also mean that none of these values will be greater than 0.
    return 0
  return table[len(intervals) % 2][len(intervals)]


