def solve_task(n, prerequisites):
    # indices of all nodes whose outdegree is 0
    available = set(range(n)) - set(map(lambda d: d[0], prerequisites))

    if not available:
        return []

    # iterate through all nodes available at the moment
    outdegree = [0 for _ in range(n)]
    for a, b in prerequisites:
        outdegree[b] += 1

    order = []
    while available:
        # Return set:
        #   x = [0, 1, 2, 3, 4];
        #   z = [2, 3, 4];
        a = available.pop()
        available = available - set(list(filter(lambda d: d[0] == a, prerequisites)))
        order.append(a)

    for prereq in prerequisites:
        if order[-1] not in prerequisites[prereq[1]]:
            return []

    return order


