def build_graph(ranks, edges):
    graph = dict()
    ranks = [set() for i in range(len(edges) + 1)]
    indegrees = [0] * len(edges)

    for u, v in edges:
        graph[u] = graph.get(u, []) + [v]
        ranks[v].add(u)
        indegrees[v] += 1

    return graph, ranks, indegrees


def topological_sort(graph, indegrees, res):
    stack, nxt = [], 0
    for i, d in enumerate(indegrees):
        if d == 0:
            stack.append(i)
    stack.sort()

    while stack:
        if len(stack) > 1:
            nxt += 1
            res.append(nxt)
        else:
            res.append(stack.pop())

        for neighbor in graph[stack[-1]]:
            indegrees[neighbor] -= 1
            if indegrees[neighbor] == 0:
                stack.append(neighbor)

    return res

