    for solution in solutions:
        for i in range(n):
            for j in range(n):
                ai, aj = solution[i], solution[j]
                if prerequisites.count([ai, aj]) != prerequisites.count([aj, ai]) + prerequisites.count([aj, ai]) + prerequisites.count([]):
                    return False
    return True


