	:param target: value in list
	:return: idx: index of the value
	"""
	idx = -1
	start = 0
	end = len(nums) - 1
	midPoint = int((start + end + 1) / 2)
	for i in range(midPoint, len(nums), -1):

		if nums[i] == target:
			idx = i
		elif nums[i] < target:
			break
		if i == 0:
			return [-1, -1]
