"""
Returns True if an undirected graph contains a cycle and False otherwise.
"""
def is_cycle(G, start):
    visited, queue = set(), [start]
    while queue:
        temp = queue.pop(0)
        if temp in visited:
            return True
        for cur in G[temp]:
            if cur not in visited:
                queue.append(cur)
        visited.add(temp)
    return False

