    def LCCTest(self, es=None, seed=None, n=10):
        import random
        random.seed(seed)
        if es is None:
            es = set()
            while len(es) < 3*n:
                e = (random.randint(0,n/2-1), random.randint(n/2,n-1))
                es.add(e)
        a,b = {},{}
        for s,e in es:
            added_s = s in a and random.random() < 0.5
            added_e = e in a and random.random() < 0.5
            if s not in a:
                a[s] = set([e])
            elif added_s:
                a[s].add(e)

            if e not in b:
                b[e] = set([s])
            elif added_e:
                b[e].add(s)

        return (a,b)

