def cycle_from(graph, start_vertex, visited):
    queue = [start_vertex]
    last_parent = None
    while queue and last_parent == None:
        current = queue.pop(0)
        if current not in visited:
            visited.add(current)
            for neighbour in graph[current]:
                if neighbour != start_vertex:
                    queue.append(neighbour)
                elif neighbour != last_parent:
                    for vertex in queue:
                        if vertex == neighbour:
                            return True
            if queue:
                last_parent = current
    return False

