def solve(n, edges):
    parents = list(range(n))

    def find_parent(u):
        if parents[u] != u:
            parents[u] = find_parent(parents[u])
        return parents[u]

    for u, v in edges:
        pu, pv = find_parent(u), find_parent(v)
        if pu != pv:
            parents[pu] = pv

    num_components = len(set(find_parent(i) for i in range(n)))
    return num_components
```

