    root1 = find(parents, node1)
    root2 = find(parents, node2)
    if root1 == root2:
        return
    if root1 > root2:
        root1, root2 = root2, root1
    parents[root2] = root1

def solve(n, edges):
    parents = list(range(n))
    for u, v in edges:
        union(parents, u, v)
