def solve(n, edges):
    class TreeNode:
        def __init__(self, data):
            self.data = data
            self.parent = None
            self.rank = 0

    def make_set(node):
        node.parent = node
        node.rank = 0

    def find_set(node):
        if node != node.parent:
            node.parent = find_set(node.parent)
        return node.parent

    def union(node1, node2):
        root1 = find_set(node1)
        root2 = find_set(node2)
        if root1 == root2:
            return False
        if root1.rank > root2.rank:
            root2.parent = root1
        elif root1.rank < root2.rank:
            root1.parent = root2
        else:
            root1.parent = root2
            root2.rank += 1
        return True

    vertices = [TreeNode(i) for i in range(n)]
    for node in vertices:
        make_set(node)
    for edge in edges:
        u, v = vertices[edge[0]], vertices[edge[1]]
        union(u, v)

    components = []
    for v in vertices:
        root = find_set(v)
        if not any(root == find_set(u) for u, c in zip(vertices, components)):
            components.append(root)

    return len(components)
