template <class IntType = uint_fast64_t>
constexpr IntType optimal_block_size(IntType device_input_size, size_t head_size,
                       size_t count) {
    assert(count < std::numeric_limits<IntType>::max() / head_size);
    // we could also check if it isn't equal to zero
    assert(device_input_size > 0);
    // need to prepare an upper bound, because of pow's function inaccuracy
    IntType upper_bound = (device_input_size + head_size - 1) / head_size * count;

    // find the nearest power of two
    long double ln_sqrt_u =
        std::log(static_cast<long double>(upper_bound)) / 2;
    IntType power_of_two = std::ldexp(1.0, std::lrint(ln_sqrt_u));
    if(power_of_two > upper_bound)
         --power_of_two;
    assert(is_power_of_two(power_of_two));

    power_of_two *= count;
    if(power_of_two == 0)
        power_of_two = 1;  // corner case when count == 0

    // if the exact number is at least as close to the nearest power of two
    // in comparison to the next greater power of two, use the number
    IntType candidate = device_input_size / head_size * count;
    IntType next_larger_power_of_two = std::ldexp(1.0, std::lrint(ln_sqrt_u) + 1);
    IntType next_larger_candidate = (device_input_size + head_size - 1) / head_size *
                                    count;
    if(power_of_two - candidate <= next_larger_power_of_two - next_larger_candidate)
        return candidate;
    return power_of_two;
}

