            current = queue.popleft()
            for neighbor in adj[current]:
                if neighbor not in visited:
                    parent[neighbor] = current
                    queue.append(neighbor)
                    visited.add(neighbor)
                elif neighbor != parent[current]:
                    return True
        return False

    adj = {i: [] for i in range(n)}

    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    visited = set()
